        Story("KO-B1-S2", "KO", "B1", "사라진 가방", listOf(
            StoryLine(0, "버스에서 내렸을 때 가방이 없다는 걸 알았어요. 여권은 가방에 없지만 공책과 호텔 열쇠는 들어 있어요.", "Otobüsten indiğimde çantamın bende olmadığını fark ettim. İçinde pasaportum değil, defterim ve otel anahtarım var."),
            StoryLine(1, "마지막으로 어디에서 봤어요? 역에 있는 카페에 두고 왔을지도 몰라요. 거기에 전화해 볼까요?", "En son nerede gördün? Belki istasyondaki kafede bıraktın. Oraya telefon edebiliriz."),
            StoryLine(0, "카페에서 나올 때는 어깨에 메고 있었어요. 버스에 탄 뒤 칠 번 좌석 위 선반에 올려놓았어요.", "Kafeden çıkarken çanta omzumdaydı. Otobüse bindiğimde yedinci koltuğun üstündeki rafa koydum."),
            StoryLine(1, "그럼 버스 회사에 전화해 봐요. 표는 아직 가지고 있어요? 운행 번호가 도움이 될 수 있어요.", "O zaman otobüs şirketini arayalım. Biletin hâlâ sende mi? Sefer numarası işimize yarayabilir."),
            StoryLine(0, "네, 주머니에 있어요. 고객 센터에서는 기사님이 종점에서 버스 안을 확인할 거라고 했어요. 소식을 들으려면 한 시간 기다려야 해요.", "Evet, bilet cebimde. Müşteri hizmetleri, şoförün son durakta aracı kontrol edeceğini söyledi. Sonuç için bir saat beklememiz gerekiyor."),
            StoryLine(1, "기다리는 동안 호텔에 가방 색깔을 알려요. 열쇠가 없으니 임시 열쇠를 받을 수 있을 거예요.", "Beklerken otele çantanın rengini bildirelim. Anahtarı kaybettiğin için sana geçici bir anahtar verebilirler."),
            StoryLine(0, "회사에서 방금 전화가 왔어요. 기사님이 선반에서 초록색 가방을 찾았대요. 공책 첫 페이지에 제 이름이 있어요. 네 시에 사무실에서 찾아갈 수 있어요.", "Şirket az önce aradı. Şoför rafta yeşil bir çanta bulmuş; defterin ilk sayfasında adım yazıyor. Çantayı saat dörtte ofisten alabilirim."),
            StoryLine(1, "잘됐네요! 공책에 적힌 이름 덕분에 주인을 확인할 수 있었군요. 먼저 임시 열쇠를 받고 사무실 주소를 확인해요.", "Güzel! Defterdeki adın çantayı tanımalarını sağlamış. Önce geçici anahtarı alalım, sonra ofisin adresini kontrol edelim.")
        ), listOf(
            StoryQuestion("Konuşmacı çantasını büyük olasılıkla nerede bıraktı?", listOf("Kafenin masasında", "Otel odasında", "Otobüsteki rafta"), 2, "Kafeden çantayla çıktı; otobüste çantayı rafa koydu ve şoför onu orada buldu."),
            StoryQuestion("Çantayı sahibine bağlayan ayrıntı hangisi?", listOf("Defterin ilk sayfasındaki ad", "Çantanın fiyatı", "Pasaport numarası"), 0, "Şoför yeşil çantayı buldu; defterdeki ad, sahibini doğrulamaya yardımcı oldu."),
            StoryQuestion("Beklerken hangi geçici çözüm öneriliyor?", listOf("Yeni bir pasaport almak", "Otelden geçici anahtar almak", "Başka bir şehre gitmek"), 1, "Pasaport çantada değil; geçici ihtiyaç otel odasına girebilmek."),
            StoryQuestion("Çanta ne zaman alınabilir?", listOf("Bir saat içinde kesinlikle otelde", "Saat dörtte şirket ofisinden", "Ertesi gün kafeden"), 1, "Son aramada saat dört ve şirket ofisi belirtiliyor; önceki bir saatlik süre bilgi beklemek içindi.")
